+        boolean satisfied = alwaysActiveRule.isSatisfied(index, tradingRecord);
+        if (!satisfied) {
+            satisfied = evaluateStages(index, tradingRecord);
+        }
+
+        traceIsSatisfied(index, satisfied);
+        return satisfied;
+    }
