+    private boolean evaluateStages(int index, TradingRecord tradingRecord) {
+        boolean satisfied = false;
+        for (int stageIndex = 0; stageIndex < triggerRules.length; stageIndex++) {
+            StageState state = stageStates[stageIndex];
